-- EcoGo! catalog seed, generated from src/data/products.csv (via the app's CSV importer)
-- and the resource lists in App.tsx / MapTab.tsx. Ids match the CSV and the app's hardcoded
-- per-product explanations (ids 1-7), so they are inserted explicitly.





-- Explicit ids were used above; move the identity sequences past them.
select setval(pg_get_serial_sequence('public.products', 'id'), (select max(id) from public.products));
select setval(pg_get_serial_sequence('public.resources', 'id'), (select max(id) from public.resources));
